meanings.gt_sql:
WITH recent_date AS (
    SELECT MAX(d) AS max_date FROM (
        SELECT "Examination Date" AS d FROM Examination WHERE ID = 27654
        UNION ALL
        SELECT Date FROM Laboratory WHERE ID = 27654
    )
);
SELECT * FROM Examination
WHERE ID = 27654 AND "Examination Date" = (SELECT max_date FROM recent_date);
SELECT * FROM Laboratory
WHERE ID = 27654 AND Date = (SELECT max_date FROM recent_date);

